// An empty material, which simply transforms the vertex and sets the color to white.

//------------------------------------
sampler SrcSamp : register(s0);

static float PI = 3.141592f;

float offset : register(c0)
<
	string UIWidget = "slider";
	float UIMin = 0.0;
//	float UIMax = 300.0;
	float UIMax = 1.0;
	float UIStep = 0.01;
	string UIName = "offset";
> = 0;

float undulate_x : register(c1)
<
	string UIWidget = "slider";
	float UIMin = 0.00;
	float UIMax = 1.0;
	float UIStep = 0.01;
	string UIName = "undulate_x";
> = 0.0;

float undulate_y : register(c2)
<
	string UIWidget = "slider";
	float UIMin = 0.00;
	float UIMax = 1.0;
	float UIStep = 0.01;
	string UIName = "undulate_y";
> = 0.0;

//-----------------------------------
float4 main( float Color : COLOR, float2 TexCoord : TEXCOORD0 ) : COLOR
{
/*
	float	val, x, y;
	
	x = OUT.Position.x;
	y = OUT.Position.y;

	val = (y * 180) + offset;
	OUT.Position.x += cos( val * PI / (180 - (150 * undulate_x)) ) * (stretch * undulate_x);
 	
	val = (x * 180) + offset;
	OUT.Position.y += cos( val * PI / (180 - (150 * undulate_y)) ) * (stretch * undulate_y);
*/

// 	IN.Color = float4(1,1,1,1);

	float2 val, undulate;
	
	undulate = float2( undulate_y, undulate_x );
	
	val = (TexCoord * 180) + ((360 * (1.0f  - undulate))  * offset);
	

	TexCoord.yx += sin( val * PI / (180 - (180 * undulate)) ) * (0.1f * undulate);

	return tex2D( SrcSamp, TexCoord ) * Color;
}
